ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	query: p('db.searchWithDRXId'),
	inputParameters: {
		"drx_id": (vars.routing.prescriptionId as String),
		"entity": p('prescription')
	}
}

%dw 2.0
output application/json
---
if (vars.request == null) null else (vars.provider match {
	case str if str == "PMD" -> vars.request ++ {
		"queryParams": {
			"event": if ( (payload.status == "Hold") or (payload.status == "Pre-Check") ) "prescription_created" else "status_change"
		}
	}
	// WellieMD takes only new-order, shipped and delivered: send new orders here, labels go out as "shipped"
	case str if str == "WLM" -> if ( (payload.status == "Hold") or (payload.status == "Pre-Check") ) (vars.request ++ {
		"uriParams": {
			"event": "new-order"
		}
	}) else null
	else -> vars.request
})
